package com.quantify.app.ui.screens.manage

import kotlinx.coroutines.runBlocking
import java.io.BufferedInputStream
import java.net.Inet4Address
import java.net.NetworkInterface
import java.net.ServerSocket
import java.net.Socket
import java.net.URLDecoder
import java.nio.charset.StandardCharsets
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

data class LanApiResponse(val status: Int = 200, val body: String = "{\"ok\":true}")

class QuantifyLanServer(
    private val dataProvider: suspend (Map<String, String>) -> String,
    private val actionHandler: suspend (String, String, String) -> LanApiResponse
) {
    companion object {
        const val STANDARD_PORT = 8765
    }

    private val running = AtomicBoolean(false)
    private var clients = Executors.newCachedThreadPool()
    private var listener: ServerSocket? = null
    private var acceptThread: Thread? = null
    val port: Int get() = listener?.localPort ?: 0
    val ipAddress: String get() = findLanIp()

    fun start() {
        check(ipAddress.isNotBlank()) { "Connect your phone to Wi-Fi first" }
        if (clients.isShutdown) clients = Executors.newCachedThreadPool()
        val socket = ServerSocket(STANDARD_PORT, 20, java.net.InetAddress.getByName(ipAddress))
        listener = socket
        running.set(true)
        acceptThread = Thread {
            while (running.get()) {
                try {
                    val client = socket.accept()
                    clients.execute { serve(client) }
                } catch (_: Exception) {
                    if (!running.get()) break
                }
            }
        }.apply { name = "Quantify-LAN-HTTP"; isDaemon = true; start() }
    }

    fun stop() {
        running.set(false)
        try { listener?.close() } catch (_: Exception) { }
        listener = null
        clients.shutdownNow()
        acceptThread = null
    }

    private fun serve(client: Socket) {
        client.use { socket ->
            try {
                socket.soTimeout = 5000
                val input = BufferedInputStream(socket.getInputStream())
                val request = readLine(input)?.split(" ") ?: return
                val headers = mutableMapOf<String, String>()
                while (true) {
                    val line = readLine(input) ?: break
                    if (line.isEmpty()) break
                    val divider = line.indexOf(':')
                    if (divider > 0) headers[line.substring(0, divider).trim().lowercase()] = line.substring(divider + 1).trim()
                }
                val length = headers["content-length"]?.toIntOrNull()?.coerceIn(0, 2_000_000) ?: 0
                val bodyBytes = ByteArray(length)
                var offset = 0
                while (offset < length) {
                    val read = input.read(bodyBytes, offset, length - offset)
                    if (read <= 0) break
                    offset += read
                }
                val body = String(bodyBytes, 0, offset, StandardCharsets.UTF_8)
                val method = request.getOrNull(0) ?: "GET"
                val target = request.getOrNull(1) ?: "/"
                val path = target.substringBefore('?')
                val query = target.substringAfter('?', "").split('&').mapNotNull { field ->
                    val pair = field.split('=', limit = 2)
                    if (pair.size == 2) URLDecoder.decode(pair[0], "UTF-8") to URLDecoder.decode(pair[1], "UTF-8") else null
                }.toMap()

                if (method != "GET" && headers["origin"] != null && headers["origin"] != "http://$ipAddress:$port") {
                    respond(socket, 403, "application/json; charset=utf-8", "{\"error\":\"Request origin rejected.\"}")
                    return
                }

                if (method == "GET" && path == "/") {
                    respond(socket, 200, "text/html; charset=utf-8", LOCAL_DASHBOARD_HTML)
                    return
                }
                if (method == "GET" && path == "/api/data") {
                    respond(socket, 200, "application/json; charset=utf-8", runBlocking { dataProvider(query) })
                    return
                }
                val result = runBlocking { actionHandler(method, path, body) }
                respond(socket, result.status, "application/json; charset=utf-8", result.body)
            } catch (_: Exception) {
                try { respond(socket, 500, "application/json; charset=utf-8", "{\"error\":\"Could not complete the request.\"}") } catch (_: Exception) { }
            }
        }
    }

    private fun respond(socket: Socket, status: Int, contentType: String, body: String) {
        val bytes = body.toByteArray(StandardCharsets.UTF_8)
        val reason = when (status) { 200 -> "OK"; 400 -> "Bad Request"; 401 -> "Unauthorized"; 403 -> "Forbidden"; 404 -> "Not Found"; 405 -> "Method Not Allowed"; 429 -> "Too Many Requests"; else -> "Internal Server Error" }
        val headers = buildString {
            append("HTTP/1.1 $status $reason\r\nContent-Type: $contentType\r\nContent-Length: ${bytes.size}\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nContent-Security-Policy: default-src 'self' 'unsafe-inline'; connect-src 'self'; form-action 'self'; frame-ancestors 'none'\r\n")
            append("\r\n")
        }
        socket.getOutputStream().apply {
            write(headers.toByteArray(StandardCharsets.US_ASCII))
            write(bytes)
            flush()
        }
    }

    private fun readLine(input: BufferedInputStream): String? {
        val bytes = ArrayList<Byte>()
        while (true) {
            val value = input.read()
            if (value < 0) return if (bytes.isEmpty()) null else String(bytes.toByteArray(), StandardCharsets.US_ASCII)
            if (value == 10) break
            if (value != 13) bytes.add(value.toByte())
            if (bytes.size > 16_384) return null
        }
        return String(bytes.toByteArray(), StandardCharsets.US_ASCII)
    }

    private fun findLanIp(): String = try {
        val addresses = NetworkInterface.getNetworkInterfaces().toList()
            .filter { it.isUp && !it.isLoopback }
            .flatMap { it.inetAddresses.toList().map { address -> it.name to address } }
            .filter { (_, address) -> address is Inet4Address && address.isSiteLocalAddress && !address.isLoopbackAddress }
        (addresses.firstOrNull { (name, _) -> name.startsWith("wlan", true) } ?: addresses.firstOrNull())?.second?.hostAddress.orEmpty()
    } catch (_: Exception) { "" }
}

