</style></head><body><header class="hero"><div><h1>Quantify</h1><p>Personal finance workspace</p></div><div class="hero-actions"><button id="themeToggle" class="button secondary" aria-label="Switch to dark mode">☾ <span>Dark mode</span></button></div></header><div id="app" class="layout"><nav id="nav"></nav><main class="main"><div class="toolbar"><h2 id="title">Overview</h2><div class="period-control"><button id="periodPrev" class="period-step" type="button" aria-label="Previous month">‹</button><label class="period-select-wrap"><span>VIEWING</span><select id="period" aria-label="Selected month"></select></label><button id="periodNext" class="period-step" type="button" aria-label="Next month">›</button></div><select id="txnFilter" class="search hidden"><option value="all">All transactions</option><option value="EXPENSE">Expenses</option><option value="INCOME">Income</option><option value="unbudgeted">Unbudgeted expenses</option></select><select id="txnSort" class="search hidden" aria-label="Sort transactions"><option value="date-newest">Newest first</option><option value="date-oldest">Oldest first</option><option value="amount-high">Amount: high to low</option><option value="amount-low">Amount: low to high</option></select><input id="search" class="search" placeholder="Search"><button id="add" class="button">+ Add</button></div><details id="txnFilterPanel" class="filterpanel hidden"><summary>More transaction filters</summary><div class="filtergrid"><select id="categoryFilter"><option value="">All categories</option></select><select id="paymentFilter"><option value="">All payment methods</option></select><select id="budgetFilter"><option value="all">Budget status: all</option><option value="budgeted">Budgeted</option><option value="unbudgeted">Unbudgeted</option></select><input id="dateFrom" type="date" aria-label="From date"><input id="dateTo" type="date" aria-label="To date"><input id="amountMin" type="number" min="0" step="0.01" placeholder="Min amount"><input id=